    best_size = 0

    seen = set()
    for color in all_colors:
        for r in range(H):
            for c in range(W):
                if grid[r][c] == color and (r, c) not in seen:
                    # BFS flood fill
                    q = deque([(r, c)])
                    seen.add((r, c))
                    size = 0
                    component_colors = set()
                    while q:
                        cr, cc = q.popleft()
                        size += 1
                        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
